def resolve(path, cwd, links):
    max_links = 8
    link_count = 0

    def split_components(p):
        return [c for c in p.split('/') if c != '' and c != '.']

    if path.startswith('/'):
        current = '/'
        components = split_components(path)
    else:
        current = cwd
        components = split_components(path)

    # use as stack: reverse so we can pop from the end in left-to-right order
    stack = components[::-1]

    while stack:
        comp = stack.pop()
        if comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            if new_path in links:
                link_count += 1
                if link_count > max_links:
                    return None
                target = links[new_path]
                if target.startswith('/'):
                    new_current = '/'
                    new_components = split_components(target)
                else:
                    new_current = current
                    new_components = split_components(target)
                # prepend the resolved link's components to remaining stack
                stack.extend(reversed(new_components))
                current = new_current
            else:
                current = new_path

    return current

